SELECT StromAus2.Elektrolyseur, StromAus2.Datum, StromAus2.Zeit, StromAusVAno.VAnolyt, StromAus2.[Cl2 + CO2 Cl] AS ConcCl2, StromAus2.[O2 Cl] AS ConcO2, EtaNaClO3Ber([StromAus2]![NaClO3 An],[StromAusVAno]![VAnolyt],[StromAus2]![NaClO3 Pb],[StromAus2]![flow rate],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]) AS µNaClO3, EtaNaOClBer([StromAus2]![NaOCl An],[StromAusVAno]![VAnolyt],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]) AS µNaOCl, EtaAlkaliBer([StromAus2]![NaOH Pb],[StromAus2]![flow rate],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]) AS µAlkali, EtaNa2CO3Ber([StromAus2]![Na2CO3 Pb],[StromAus2]![flow rate],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]) AS µNa2CO3, EtaHClBer([StromAus2]![HCl Pb],[StromAus2]![flow rate],[StromAus2]![HCl An],[StromAusVAno]![VAnolyt],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]) AS µHCl, EtaO2Ber([ConcO2],[ConcCl2],[µNaClO3],[µNaOCl]) AS µO2, EtaO2Ber([Analyse Chlorgas]![O2 Cl],[Analyse Chlorgas]![Cl2 + CO2 Cl],[µNaClO3],[µNaOCl]) AS µO2alt, EtaMembraneBer([µO2],[µNaClO3],[µNaOCl],[µHCl],[µNa2CO3],[µAlkali]) AS µNaOH, GEtGewAKF() AS CheckAKF, AktOClAnalyse() AS CheckClO, AktAnsaeurung() AS CheckAnsaeurung
FROM tblGewDaten, ((StromAus2 INNER JOIN StromAusVAno ON (StromAus2.Datum = StromAusVAno.Datum) AND (StromAus2.Elektrolyseur = StromAusVAno.Elektrolyseur)) INNER JOIN UnElekFV ON (StromAus2.Datum = UnElekFV.Datum) AND (StromAus2.Elektrolyseur = UnElekFV.Elektrolyseur)) INNER JOIN [Analyse Chlorgas] ON (StromAus2.Datum = [Analyse Chlorgas].Datum) AND (StromAus2.Elektrolyseur = [Analyse Chlorgas].Elektrolyseur)
WHERE (((StromAus2.Elektrolyseur)=(SELECT Bezeichnung FROM tblElektrolyseurbezeichnung WHERE tblGewDaten.IDElektrolyseurUnCeSpcElektrolyseur = tblElektrolyseurbezeichnung.Nr)) AND ((StromAus2.Datum)>=[tblGewDaten].[Anfangsdatum] And (StromAus2.Datum)<=[tblGewDaten].[Enddatum]) AND ((StromAusVAno.VAnolyt)<>(-1)) AND ((StromAus2.[Cl2 + CO2 Cl]) Is Not Null) AND ((StromAus2.[O2 Cl]) Is Not Null) AND ((EtaNaClO3Ber([StromAus2]![NaClO3 An],[StromAusVAno]![VAnolyt],[StromAus2]![NaClO3 Pb],[StromAus2]![flow rate],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]))<>(-1)) AND ((EtaNaOClBer([StromAus2]![NaOCl An],[StromAusVAno]![VAnolyt],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]))<>(-1)) AND ((EtaAlkaliBer([StromAus2]![NaOH Pb],[StromAus2]![flow rate],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]))<>(-1)) AND ((EtaNa2CO3Ber([StromAus2]![Na2CO3 Pb],[StromAus2]![flow rate],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]))<>(-1)) AND ((EtaHClBer([StromAus2]![HCl Pb],[StromAus2]![flow rate],[StromAus2]![HCl An],[StromAusVAno]![VAnolyt],[UnElekFV]![Elementzahl],[UnElekFV]![I Gesamt]))<>(-1)))
ORDER BY StromAus2.Elektrolyseur, StromAus2.Datum;
